  assert.equal("almacen" in crearStockAjustado(AJUSTE), false);
  for (const malo of ["ALM-1", "alm-01", "ALM-001", "ALM-01 ", "", 1])
    assert.throws(() => crearStockAjustado({ ...AJUSTE, almacen: malo }), RangeError);
});

